/**
 * Scene 5 — University Discovery Atlas: institution model + selectors.
 *
 * DATA: `institutions.data.json` is GENERATED by `scripts/verify-institutions.mjs` from `data/institutions/seed.json`.
 * Each fact in it was matched against the live official web page (the evidence quote and URL are stored in
 * `sources`); a field with no matching evidence is `null` / empty and the UI shows "Information coming soon".
 * Never edit the JSON by hand and never add a value that has no evidence. There are deliberately NO fields for
 * rankings, fees, placements, salaries, cut-offs, accreditation grades or entrance requirements until a sourced
 * record exists (add the field to the seed + script first).
 *
 * `coordinates` is always `null` for now: no verified location data is stored, so the atlas is a SCHEMATIC regional
 * constellation (not a geographic map). When verified coordinates exist they can be added without changing the UI model.
 */

import type { DomainId } from '@/theme/tokens';
import raw from './institutions.data.json';

export type RegionId = 'north' | 'south' | 'east' | 'west' | 'central' | 'international';
export type InstitutionType = 'public' | 'private' | 'deemed' | 'ini' | 'specialised';

export interface Region {
  id: RegionId;
  label: string;
  /** one plain line shown in the panel */
  note: string;
}

export const REGIONS: readonly Region[] = [
  { id: 'north', label: 'North India', note: 'Delhi, Haryana, Punjab, Rajasthan, Himachal Pradesh, Jammu & Kashmir and nearby.' },
  { id: 'west', label: 'West India', note: 'Maharashtra, Gujarat, Goa and nearby.' },
  { id: 'central', label: 'Central India', note: 'Uttar Pradesh, Madhya Pradesh, Chhattisgarh and Uttarakhand.' },
  { id: 'east', label: 'East India', note: 'West Bengal, Odisha, Bihar, Jharkhand and the North-East.' },
  { id: 'south', label: 'South India', note: 'Tamil Nadu, Karnataka, Kerala, Andhra Pradesh and Telangana.' },
  { id: 'international', label: 'International', note: 'Institutions outside India.' },
];

/**
 * State → region. Follows India's five Zonal Councils (Northern, Central, Eastern, Western, Southern) with the
 * North-East grouped under East. Editorial grouping for browsing; it is not an official classification of institutions.
 */
export const REGION_BY_STATE: Record<string, RegionId> = {
  Delhi: 'north', Haryana: 'north', Punjab: 'north', Rajasthan: 'north', 'Himachal Pradesh': 'north', 'Jammu & Kashmir': 'north', Chandigarh: 'north', Ladakh: 'north',
  'Uttar Pradesh': 'central', 'Madhya Pradesh': 'central', Chhattisgarh: 'central', Uttarakhand: 'central',
  Maharashtra: 'west', Gujarat: 'west', Goa: 'west',
  'West Bengal': 'east', Odisha: 'east', Bihar: 'east', Jharkhand: 'east', Assam: 'east', Meghalaya: 'east', Tripura: 'east', Manipur: 'east', Mizoram: 'east', Nagaland: 'east', 'Arunachal Pradesh': 'east', Sikkim: 'east',
  'Tamil Nadu': 'south', Karnataka: 'south', Kerala: 'south', 'Andhra Pradesh': 'south', Telangana: 'south', Puducherry: 'south',
};

export const TYPE_LABELS: Record<InstitutionType, string> = {
  public: 'Public universities',
  private: 'Private universities',
  deemed: 'Deemed-to-be universities',
  ini: 'Institutes of national importance',
  specialised: 'Specialised institutions',
};
export const TYPE_ORDER: readonly InstitutionType[] = ['public', 'private', 'deemed', 'ini', 'specialised'];

export interface SourceNote {
  field: string;
  url: string;
  quote: string;
}

export interface Institution {
  /** institutionId */
  id: string;
  name: string;
  shortName: string;
  slug: string;
  city: string;
  state: string;
  country: string;
  region: RegionId;
  /** null = not verified yet */
  institutionType: InstitutionType | null;
  officialWebsite: string;
  establishedYear: number | null;
  academicDomains: readonly DomainId[];
  /** verified course names; empty until course data is verified per institution */
  availableCourses: readonly string[];
  /** verified [lat, lng] only; null until such data exists */
  coordinates: readonly [number, number] | null;
  dataSources: readonly SourceNote[];
  /** ISO date the facts were last checked against the official pages */
  lastVerified: string;
}

type RawInstitution = (typeof raw.institutions)[number];

export const INSTITUTIONS: readonly Institution[] = raw.institutions
  .map((r: RawInstitution): Institution => ({
    id: r.id,
    name: r.name,
    shortName: r.shortName,
    slug: r.slug,
    city: r.city,
    state: r.state,
    country: r.country,
    region: REGION_BY_STATE[r.state] ?? 'international',
    institutionType: r.institutionType as InstitutionType | null,
    officialWebsite: r.officialWebsite,
    establishedYear: r.establishedYear,
    academicDomains: r.academicDomains as DomainId[],
    availableCourses: r.availableCourses as string[],
    coordinates: null,
    dataSources: r.sources,
    lastVerified: r.lastVerified,
  }))
  .sort((a, b) => a.shortName.localeCompare(b.shortName));

export const DATA_LAST_VERIFIED: string = raw.lastVerified;

export interface AtlasFilters {
  type: InstitutionType | null;
  domain: DomainId | null;
}

export const matches = (i: Institution, f: AtlasFilters) =>
  (f.type === null || i.institutionType === f.type) && (f.domain === null || i.academicDomains.includes(f.domain));

export const inRegion = (id: RegionId) => INSTITUTIONS.filter((i) => i.region === id);

export const TYPE_NOTE_UNAVAILABLE = 'Information coming soon';
